import { expect, test } from 'bun:test';
import Ajv from 'ajv';
import addFormats from 'ajv-formats';
import { readdirSync, readFileSync } from 'node:fs';
import { API_VERSION, ORKFLOW_PLACEHOLDER, automationPlaceholder } from '../src/lib/placeholders';

// The authored documents' JSON Schemas (docs/schemas/, generated by
// `go run ./internal/schemas/cmd/genschemas`), compiled the strict way an
// editor's validator would, and held to every document this repository ships.

const repo = `${import.meta.dir}/../..`;
const read = (path: string) => readFileSync(`${repo}/${path}`, 'utf8');
const schema = (name: string) => JSON.parse(read(`docs/schemas/${name}`));
const NAMES = ['orkflow.v1.json', 'automation.v1.json', 'activityinterface.v1.json', 'orkstack.v1.json'];

function compile(name: string) {
	const ajv = new Ajv({ allErrors: true, strict: true, strictRequired: false, allowUnionTypes: true });
	// Exactly the formats the generator emits: a new `format` fails this
	// strict compile until someone registers it on purpose.
	addFormats(ajv, ['date-time']);
	return ajv.compile(schema(name));
}

const validators = Object.fromEntries(NAMES.map((name) => [name, compile(name)]));

const HEADER = `apiVersion: ${API_VERSION}\nkind: Orkflow\n`;
function expectValid(label: string, doc: unknown, kindSchema: string) {
	for (const name of ['orkstack.v1.json', kindSchema]) {
		const validate = validators[name];
		const ok = validate(doc);
		expect(ok ? '' : `${label} against ${name}: ${JSON.stringify(validate.errors?.slice(0, 5))}`).toBe('');
	}
}

test('every generated schema compiles under strict mode', () => {
	for (const name of NAMES) {
		let error = '';
		try {
			compile(name);
		} catch (e) {
			error = String(e);
		}
		expect(`${name}: ${error}`).toBe(`${name}: `);
	}
});

test('API_VERSION is the generated schemas’ apiVersion', () => {
	expect(schema('orkflow.v1.json').properties.apiVersion.const).toBe(API_VERSION);
	expect(schema('automation.v1.json').properties.apiVersion.const).toBe(API_VERSION);
	expect(schema('activityinterface.v1.json').properties.apiVersion.const).toBe(API_VERSION);
	expect(schema('orkstack.v1.json').properties.apiVersion.const).toBe(API_VERSION);
});

test('every shipped document validates against the dispatcher and its kind', () => {
	let count = 0;
	for (const file of readdirSync(`${repo}/examples`).filter((f) => f.endsWith('.ork.yaml')).sort()) {
		expectValid(`examples/${file}`, Bun.YAML.parse(read(`examples/${file}`)), 'orkflow.v1.json');
		count++;
	}
	for (const file of readdirSync(`${repo}/examples/automation`).filter((f) => f.endsWith('.ork.yaml')).sort()) {
		expectValid(`examples/automation/${file}`, Bun.YAML.parse(read(`examples/automation/${file}`)), 'automation.v1.json');
		count++;
	}
	for (const file of readdirSync(`${repo}/internal/automation/testdata`).filter((f) => /^export-.*\.golden$/.test(f)).sort()) {
		expectValid(file, Bun.YAML.parse(read(`internal/automation/testdata/${file}`)), 'automation.v1.json');
		count++;
	}
	expectValid('ORKFLOW_PLACEHOLDER', Bun.YAML.parse(ORKFLOW_PLACEHOLDER), 'orkflow.v1.json');
	expectValid("automationPlaceholder('default')", Bun.YAML.parse(automationPlaceholder('default')), 'automation.v1.json');
	count += 2;
	// Two headered vectors cover what no example does: every feature in one
	// document, and present-but-empty inputs:/with:. TestCompile_SchemaVectorsCompile
	// compiles them, so a vector the compiler refuses cannot sit here.
	for (const file of readdirSync(`${repo}/internal/dsl/testdata/schema-vectors`).filter((f) => f.endsWith('.ork.yaml')).sort()) {
		expectValid(`schema-vectors/${file}`, Bun.YAML.parse(read(`internal/dsl/testdata/schema-vectors/${file}`)), 'orkflow.v1.json');
		count++;
	}
	expect(count > 25).toBe(true);
});

const ork = (body: string) => Bun.YAML.parse(HEADER + 'name: x\n' + body);
const automation = (body: string) => Bun.YAML.parse(`apiVersion: ${API_VERSION}\nkind: Automation\nnamespace: n\n` + body);

function refusedAt(label: string, doc: unknown, name: string, path: string) {
	const validate = validators[name];
	expect(`${label}: ${validate(doc)}`).toBe(`${label}: false`);
	const paths = (validate.errors ?? []).map((error) => error.instancePath);
	expect(paths).toContain(path);
}

test('the schemas refuse what the compiler refuses, at its path', () => {
	refusedAt('no header', Bun.YAML.parse('name: x\ntasks:\n  - id: a\n    uses: shell\n'), 'orkstack.v1.json', '');
	refusedAt('apiVersion orkstack/v2', Bun.YAML.parse('apiVersion: orkstack/v2\nkind: Orkflow\nname: x\ntasks: [{id: a, uses: shell}]\n'), 'orkstack.v1.json', '/apiVersion');
	refusedAt('a misspelled need:', ork('tasks:\n  - id: a\n    uses: shell\n    need: [b]\n'), 'orkflow.v1.json', '/tasks/0');
	refusedAt('join: any_failure', ork('tasks:\n  - id: a\n    uses: shell\n    join: any_failure\n'), 'orkflow.v1.json', '/tasks/0/join');
	refusedAt('network: host', ork('tasks:\n  - id: a\n    uses: shell\n    network: host\n'), 'orkflow.v1.json', '/tasks/0/network');
	refusedAt('uses and await', ork('tasks:\n  - id: a\n    uses: shell\n    await: {timeout_seconds: 5}\n'), 'orkflow.v1.json', '/tasks/0/uses');
	refusedAt('command on an awaited task', ork('tasks:\n  - id: a\n    await: {timeout_seconds: 5}\n    command: [x]\n'), 'orkflow.v1.json', '/tasks/0/command');
	refusedAt('env on a composed task', ork('tasks:\n  - id: a\n    uses: orkflow:child@1\n    env: {A: b}\n'), 'orkflow.v1.json', '/tasks/0/env');
	refusedAt('http with no url', ork('tasks:\n  - id: a\n    uses: http\n    with: {op: get}\n'), 'orkflow.v1.json', '/tasks/0/with');
	refusedAt('http op fetch', ork('tasks:\n  - id: a\n    uses: http\n    with: {url: x, op: fetch}\n'), 'orkflow.v1.json', '/tasks/0/with/op');
	refusedAt('tasks: []', ork('tasks: []\n'), 'orkflow.v1.json', '/tasks');
	refusedAt('automation without namespace', Bun.YAML.parse(`apiVersion: ${API_VERSION}\nkind: Automation\n`), 'orkstack.v1.json', '');
	refusedAt('overlap: sometimes', automation('schedules:\n  s: {orkflow: x, cron: "@daily", overlap: sometimes}\n'), 'automation.v1.json', '/schedules/s/overlap');
	refusedAt('start_at: tomorrow', automation('schedules:\n  s: {orkflow: x, cron: "@daily", start_at: tomorrow}\n'), 'automation.v1.json', '/schedules/s/start_at');
	refusedAt('a secret named ..', ork('tasks:\n  - id: a\n    uses: shell\n    secrets: [{name: "..", source: "env:X"}]\n'), 'orkflow.v1.json', '/tasks/0/secrets/0/name');
	// The deliberate classes (docs/DSL.md, "Editor support"): V, N, I and D.
	refusedAt('version: 2 (V)', Bun.YAML.parse(HEADER + 'name: x\nversion: 2\ntasks:\n  - id: a\n    uses: busybox:1\n'), 'orkflow.v1.json', '/version');
	refusedAt('env: ~ (N)', ork('tasks:\n  - id: a\n    uses: busybox:1\n    env: ~\n'), 'orkflow.v1.json', '/tasks/0/env');
	refusedAt('timeout_seconds: 1.5 (I)', ork('tasks:\n  - id: a\n    uses: busybox:1\n    timeout_seconds: 1.5\n'), 'orkflow.v1.json', '/tasks/0/timeout_seconds');
	refusedAt('inputs type strin (D)', Bun.YAML.parse(HEADER + 'name: x\ninputs: {i: {type: strin}}\ntasks:\n  - id: a\n    uses: busybox:1\n'), 'orkflow.v1.json', '/inputs/i/type');
	refusedAt('an await field without type', ork('tasks:\n  - id: a\n    await: {timeout_seconds: 5, schema: {ok: {required: true}}}\n'), 'orkflow.v1.json', '/tasks/0/await/schema/ok');
	refusedAt('an await field with a default', ork('tasks:\n  - id: a\n    await: {timeout_seconds: 5, schema: {ok: {type: boolean, default: true}}}\n'), 'orkflow.v1.json', '/tasks/0/await/schema/ok');
	refusedAt('a trigger description 12', automation('triggers:\n  t: {orkflow: x, description: 12}\n'), 'automation.v1.json', '/triggers/t/description');
});

test('the schemas accept what the compiler accepts', () => {
	const accepted: [string, unknown, string][] = [
		['an http body mapping', ork('tasks:\n  - id: a\n    uses: http\n    with: {url: x, op: post, body: {m: 1}}\n'), 'orkflow.v1.json'],
		['an http body list', ork('tasks:\n  - id: a\n    uses: http\n    with: {url: x, op: post, body: [1]}\n'), 'orkflow.v1.json'],
		['an http body string', ork('tasks:\n  - id: a\n    uses: http\n    with: {url: x, op: post, body: hi}\n'), 'orkflow.v1.json'],
		['a templated timeoutSeconds', ork("tasks:\n  - id: a\n    uses: http\n    with: {url: x, timeoutSeconds: '{{ .inputs.t }}'}\n"), 'orkflow.v1.json'],
		['a templated op', ork("tasks:\n  - id: a\n    uses: http\n    with: {url: x, op: '{{ .inputs.op }}'}\n"), 'orkflow.v1.json'],
		['start_at an instant', automation('schedules:\n  s: {orkflow: x, cron: "@daily", start_at: "2026-01-02T03:04:05Z"}\n'), 'automation.v1.json'],
		['env numbers and booleans', ork('tasks:\n  - id: a\n    uses: busybox:1\n    env: {PORT: 8080, DEBUG: true}\n'), 'orkflow.v1.json'],
		['resources numbers', ork('tasks:\n  - id: a\n    uses: busybox:1\n    resources: {cpu: 2, memory: 4}\n'), 'orkflow.v1.json'],
		['a label number', Bun.YAML.parse(HEADER + 'name: x\nlabels: {n: 1}\ntasks:\n  - id: a\n    uses: busybox:1\n'), 'orkflow.v1.json'],
		['command [1, true]', ork('tasks:\n  - id: a\n    uses: busybox:1\n    command: [1, true]\n'), 'orkflow.v1.json'],
		['an await field', ork('tasks:\n  - id: a\n    await: {timeout_seconds: 5, schema: {ok: {type: boolean, required: true}}}\n'), 'orkflow.v1.json']
	];
	for (const [label, doc, name] of accepted) {
		const validate = validators[name];
		const ok = validate(doc);
		expect(ok ? label : `${label}: ${JSON.stringify(validate.errors?.slice(0, 4))}`).toBe(label);
	}
});

// The activity interface documents (kind: ActivityInterface): every image this
// repository builds beside an interface.ork.yaml declares one, and the schema
// refuses what ParseInterfaceDocument refuses, at its path.
test('every shipped activity interface validates, and the schema refuses what pack refuses', () => {
	let count = 0;
	for (const parent of ['images', 'examples']) {
		for (const dir of readdirSync(`${repo}/${parent}`).sort()) {
			let source: string;
			try {
				source = read(`${parent}/${dir}/interface.ork.yaml`);
			} catch {
				continue;
			}
			expectValid(`${parent}/${dir}/interface.ork.yaml`, Bun.YAML.parse(source), 'activityinterface.v1.json');
			count++;
		}
	}
	expect(count).toBe(8);
	const iface = (body: string) => Bun.YAML.parse(`apiVersion: ${API_VERSION}\nkind: ActivityInterface\n` + body);
	expectValid('empty fields, values and ops', iface('fields:\nvalues:\nops:\n  get:\n'), 'activityinterface.v1.json');
	refusedAt('a written schemaVersion', iface('schemaVersion: 1\n'), 'activityinterface.v1.json', '');
	refusedAt('type: text', iface('fields:\n  a:\n    type: text\n'), 'activityinterface.v1.json', '/fields/a/type');
	refusedAt('a field with no type', iface('fields:\n  a:\n    required: true\n'), 'activityinterface.v1.json', '/fields/a');
	refusedAt('an op that is not lowercase', iface('ops:\n  Get: {}\n'), 'activityinterface.v1.json', '/ops');
	refusedAt('a key past 128 bytes', iface(`values:\n  ${'k'.repeat(129)}:\n    type: string\n`), 'activityinterface.v1.json', '/values');
	refusedAt('an unknown key, through the dispatcher', iface('field: {}\n'), 'orkstack.v1.json', '');
});
